function o(n){return n==="inbound_order"?["receiving","qc","putaway","putaway_quarantine","routing","dispatch"]:["pick","pack","shipping_details","dispatch","routing"]}function p(n,e){const t=o(e);return[...n].sort((r,a)=>{const i=t.indexOf(r.taskType),c=t.indexOf(a.taskType),s=i>=0?i:Number.MAX_SAFE_INTEGER,u=c>=0?c:Number.MAX_SAFE_INTEGER;return s-u})}function d(n,e,t){const r=p(n,e),a=r.findIndex(i=>i.id===t);return a>=0?r[a+1]:void 0}function k(n,e){switch(n){case"receiving":return e(["Receiving","استلام"]);case"qc":return e(["Quality check","فحص الجودة"]);case"putaway":return e(["Putaway","تخزين"]);case"putaway_quarantine":return e(["Putaway (quarantine)","تخزين (حجر صحي)"]);case"pick":return e(["Pick","التقاط"]);case"pack":return e(["Pack","تغليف"]);case"shipping_details":return e(["Shipping details","تفاصيل الشحن"]);case"dispatch":return e(["Dispatch","إرسال"]);case"routing":return e(["Routing","توجيه"]);default:return n.replace(/_/g," ")}}function f(n,e){return e?`/tasks/${n}?companyId=${encodeURIComponent(e)}`:`/tasks/${n}`}export{d as f,k as p,f as t};
